struct file {
    enum { FD_NONE, FD_PIPE, FD_INODE } type;  // 文件类型
    int ref;                                    // 引用计数
    char readable;                              // 是否可读
    char writable;                              // 是否可写
    struct pipe *pipe;                          // 指向 pipe 结构（如果是管道）
    struct inode *ip;                           // 指向 inode（如果是磁盘文件）
    uint off;                                   // 文件偏移量
};

int pipealloc(struct file **f0, struct file **f1)
{
    struct pipe *pi = (struct pipe*)kalloc();
    pi->readopen = 1;
    pi->writeopen = 1;
    pi->nwrite = 0;
    pi->nread = 0;

    *f0 = filealloc();  // 分配读端文件
    (*f0)->type = FD_PIPE;
    (*f0)->readable = 1;
    (*f0)->writable = 0;
    (*f0)->pipe = pi;

    *f1 = filealloc();  // 分配写端文件
    (*f1)->type = FD_PIPE;
    (*f1)->readable = 0;
    (*f1)->writable = 1;
    (*f1)->pipe = pi;
    return 0;
}

