    close(0);           // 关闭标准输入
    dup(pipe_fd[0]);    // 将读端复制到 fd 0
    close(pipe_fd[0]);
    close(pipe_fd[1]);  // 为什么这里要关闭写端？
    exec("wc", ...);
} else {
    // 父进程（cat）
    close(1);           // 关闭标准输出
    dup(pipe_fd[1]);    // 将写端复制到 fd 1
    close(pipe_fd[0]);  // 为什么这里要关闭读端？
    close(pipe_fd[1]);
    exec("cat", ...);
}

